ALTER POLICY "Validated website submissions" ON public.leads WITH CHECK (status='novo' AND origem='site' AND notes IS NULL AND char_length(btrim(coalesce(name,''))) BETWEEN 2 AND 200 AND whatsapp ~ '^[0-9()+ .-]{10,25}$' AND char_length(city) <= 200 AND char_length(coalesce(message,'')) <= 10000 AND char_length(coalesce(email,'')) <= 254 AND meta_lead_id IS NULL AND meta_campaign_id IS NULL AND campaign_name IS NULL AND category IS NULL AND whatsapp_received_at IS NULL AND sincronizado_meta=false AND ultimo_retorno_meta IS NULL AND ultimo_erro_meta IS NULL AND tag_origem_manual=false AND tag_origem_alterada_por IS NULL AND created_at BETWEEN now()-interval '5 minutes' AND now()+interval '1 minute');